import{_ as e,c as i,o as t,a3 as s}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"隱私權選擇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy-choices.md","filePath":"zh-TW/guide/privacy-choices.md","lastUpdated":1786595765000}'),r={name:"zh-TW/guide/privacy-choices.md"};function o(l,a,h,n,c,d){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="隱私權選擇" tabindex="-1">隱私權選擇 <a class="header-anchor" href="#隱私權選擇" aria-label="Permalink to &quot;隱私權選擇&quot;">​</a></h1><p>ClipboardxAI 是一款本機優先的應用程式。由於你的資料保留在你的裝置上，我們不會蒐集、販售或分享任何個人資訊。</p><h2 id="我們在本地持有的資料" tabindex="-1">我們在本地持有的資料 <a class="header-anchor" href="#我們在本地持有的資料" aria-label="Permalink to &quot;我們在本地持有的資料&quot;">​</a></h2><p>ClipboardxAI 將所有資料儲存在你 Mac 的本地上：</p><ul><li>剪貼簿歷史與應用程式偏好設定</li><li>自訂動作與設定</li><li>API key（位於 Keychain 中，僅在你設定雲端供應商時）</li><li>除錯日誌（若已啟用）</li></ul><p>這些資料都不會由應用程式本身上傳到任何伺服器。</p><h2 id="雲端-ai-加入選項" tabindex="-1">雲端 AI 加入選項 <a class="header-anchor" href="#雲端-ai-加入選項" aria-label="Permalink to &quot;雲端 AI 加入選項&quot;">​</a></h2><p>雲端 AI 功能<strong>預設為關閉</strong>。它們只會在你觸發雲端動作時，使用你自己的 API key，將內容傳送給你所選擇的供應商。你可以在 <strong>Settings → AI（設定 → AI）</strong> 中檢視或刪除已設定的供應商。</p><h2 id="你的權利" tabindex="-1">你的權利 <a class="header-anchor" href="#你的權利" aria-label="Permalink to &quot;你的權利&quot;">​</a></h2><p>由於 ClipboardxAI 不會在我們的伺服器上蒐集或儲存個人資料，因此我們沒有任何可供存取、刪除或移轉的個人資料。你所有的資料都可以直接在應用程式內管理，或是透過移除應用程式的容器資料夾來處理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><h2 id="不販售" tabindex="-1">不販售 <a class="header-anchor" href="#不販售" aria-label="Permalink to &quot;不販售&quot;">​</a></h2><p>ClipboardxAI 不會販售任何個人資訊。我們不使用任何形式的第三方分析、廣告或追蹤服務。</p><h2 id="聯絡方式" tabindex="-1">聯絡方式 <a class="header-anchor" href="#聯絡方式" aria-label="Permalink to &quot;聯絡方式&quot;">​</a></h2><p>若你對隱私權選擇有任何疑問，請在以下位置開啟一個 issue： <code>https://github.com/clipboardxAI/clipboard-site/issues</code></p>',15)])])}const b=e(r,[["render",o]]);export{u as __pageData,b as default};
